"""Pinyon, kremayer ve motor kızağı için kaynak sınırlı ürün metinleri."""
import json
from html import escape

from aile_hazirla import ROOT, slug, table
from hazirla import ascii_text, tr_lower

BASE = 'KREMAYER RAYLAR VE PİNYON DİŞLİLER'
CATEGORIES = {'PD': BASE + '>PİNYON DİŞLİLER>DÜZ PİNYONLAR', 'KR': BASE + '>KREMAYER RAYLAR>DÜZ KREMAYERLER', 'MKI': 'MOTOR KIZAKLARI'}


def identity(raw):
    model, family, m = raw['model'], raw['aile'], raw['nominal']
    values = {k: v['deger'] for k, v in raw['degerler'].items()}
    if family == 'PD':
        if 'Diş Sayısı (Z)' not in values:
            return f'{model} Düz Pinyon Dişli Modül {m} - {values["Dış Çap (De)"]}'
        return f'{model} Düz Pinyon Dişli Modül {m} - {values["Diş Sayısı (Z)"]} Diş {values["Dış Çap (De)"]}'
    if family == 'KR':
        if 'Kesit Ölçüsü (a)' in values:
            dims = '×'.join(values[k].split()[0] for k in ['Kesit Ölçüsü (a)', 'Kesit Ölçüsü (b)', 'Boy (L)']) + ' mm'
        elif raw['orka_site']:
            dims = '25×25×1000 mm'
        else:
            dims = ''
        kind = 'Kapı Altı Kremayer' if raw.get('kapi_alti') else 'Düz Kremayer'
        return f'{model} {kind} Modül {m} {dims}'.strip()
    if family == 'MKI':
        return f'MKİ {model} İnce Seri Motor Kızağı {values["Ölçü (C)"]}'
    raise ValueError('Bilinmeyen aile: ' + family)


def sections(raw, index):
    model, family, m = raw['model'], raw['aile'], raw['nominal']
    v = {k: x['deger'] for k, x in raw['degerler'].items()}
    if family == 'PD':
        if 'Diş Sayısı (Z)' not in v:
            de, dp = v['Dış Çap (De)'], v['Bölüm Dairesi Çapı (Dp)']
            return [('Düz Pinyon Yapısı', f'{model}, modül {m} düz pinyon grubundadır. Dış çapı {de}, bölüm dairesi çapı {dp} olarak verilir. Bir kremayerle birlikte kullanıldığında dönme hareketinin doğrusal harekete çevrilmesinde görev alır. Dış çap parçanın kapladığı zarfı, bölüm dairesi ise dişli eşleşmesinin geometrik referansını tanımlar. Bu çaplar birbirinin yerine kullanılmamalı; dişli çevresinde bırakılacak montaj boşluğu ayrı değerlendirilmelidir.'), ('Diş ve Karşı Parça Seçimi', f'{model} siparişinde diş sayısı ayrıca netleştirilmelidir; yalnız model numarasından hareketle diş sayısını kesin kabul etmeyin. Modül {m} bilgisi karşı kremayeri seçmenin ilk koşuludur, ancak tek başına bağlantı ve çalışma uyumunu belirlemez. Diş profili, karşı parçanın ekseni, boşluk ayarı ve tahrik düzeni birlikte incelenir. {dp} bölüm dairesi çapı ile {de} dış çap farklı amaçlarla kullanılır; karşı parçayı yalnız dış çapa göre seçmek doğru değildir.'), ('Mil Bağlantısı ve Yerleşim', f'{model} teknik listesinde küçük d değeri {v["Ölçü (d)"]}, büyük D değeri {v["Ölçü (D)"]} olarak korunmuştur. Bu harflerden birini doğrudan bitmiş mil deliği, kama kanalı veya göbek boyu kabul etmeyin. Mil üzerine montaj biçimi ve gerekli son işleme ölçüleri siparişten önce karşılaştırılır. Modül {m} pinyonun diş genişliği ile göbek uzunluğu ayrıca belirlenmeden mevcut makinedeki boşluğa tam oturacağı varsayılmamalıdır.'), ('Kullanım Alanları', f'{model}; kremayerli konumlama mekanizmaları, makine besleme eksenleri ve doğrusal taşıma tahriklerinde değerlendirilebilir. {de} dış çapın yerleşime uygunluğu, modül {m} karşı parçayla çalışma koşulları ve motor-redüktör düzeni beraber ele alınır. Pinyon tahrik elemanıdır; hareketli tablanın kılavuzlanmasını kendi başına sağlamaz. Malzeme ve ısıl işlem bilgisi belirtilmeden bu model için izin verilen tork, çalışma ömrü veya taşıma kapasitesi çıkarılamaz.'), ('Montaj ve Bakım', f'{model} montajında karşı kremayerin uzunlamasına hizası ve ek yerlerindeki diş devamlılığı kontrol edilir. {m} modüllü mekanizmada yalnız kısa bir noktada rahat çalışma görülmesi, bütün hareket boyunca doğru boşluk bulunduğunu göstermez. Pinyon düşük hızda eksen boyunca yürütülerek sıkışma ve darbe kontrolü yapılır. Yağlama ve koruyucu düzen çalışma ortamına uygun seçilmeli; talaş veya yabancı parçaların diş arasına girmesi önlenmelidir.')]
        z, de, dp = v['Diş Sayısı (Z)'], v['Dış Çap (De)'], v['Bölüm Dairesi Çapı (Dp)']
        intro = [f'{model}, modül {m} ve {z} dişli düz bir pinyondur. Dairesel hareketin bir kremayer boyunca doğrusal harekete dönüştürülmesinde veya uygun karşı dişliyle güç aktarımında kullanılır. {de} dış çap, dişlerin en dış zarfını tanımlar; {dp} bölüm dairesi çapı ise eşleşen dişlerin geometrik çalışma dairesine ait ölçüdür. Bu iki çapın birbirine karıştırılmaması, makine üzerindeki boşluğun ve karşı parçanın yerleşiminin doğru değerlendirilmesini sağlar.', f'Modül {m} sınıfındaki {model}, {z} diş sayısıyla seçilen düz pinyon dişlidir. Bir eksenin tahrik tasarımında pinyonun diş sayısı, karşı kremayerin modülü ve redüktörün düzeni birlikte ele alınır. {de} dış çapa sahip bu modelin bölüm dairesi {dp} değerindedir. Dış çap, parçanın kapladığı hacmi; bölüm dairesi ise dişli eşleşmesinin geometrik referansını tanımlar. Yalnız dış çapa bakarak karşı kremayer seçmek doğru değildir.', f'{z} dişli {model}, modül {m} düz dişli grubunda yer alan bir pinyondur. Dış diş zarfı {de}, bölüm dairesi çapı {dp} olarak verilir. Hareket aktarımında bu ölçüler, dişli çevresindeki mekanik boşluk ve karşı parçanın merkez yerleşimi için farklı amaçlarla kullanılır. Ürün bir zincir dişlisi değildir; diş sayısının aynı olması zincir, triger veya farklı modüldeki bir kremayerle eşleşeceği anlamına gelmez.'][index % 3]
        return [('Düz Dişli Yapısı', intro), ('Karşı Parça ve Modül Seçimi', f'{model} ile çalışacak kremayerin modülü {m} olmalıdır; modülün aynı olması yine de bütün montaj koşullarının tamamlandığı anlamına gelmez. Diş profili, çalışma boşluğu, eksen konumu ve karşı parçanın bağlantısı birlikte kontrol edilir. {z} diş sayısı, aynı modüldeki başka bir pinyona geçildiğinde hareket geometrisinin değişeceğini gösterir. {dp} bölüm dairesi, çalışma yerleşiminde dikkate alınır; bu çapın dış çap olan {de} yerine kullanılacağı yerler tasarımda ayrı tutulmalıdır.'), ('Bağlantı ve Yerleşim Kontrolü', f'{model} teknik listesinde küçük d ölçüsü {v["Ölçü (d)"]}, büyük D ölçüsü {v["Ölçü (D)"]} olarak korunmuştur. Bu iki harfe bakarak birini otomatik olarak bitmiş mil deliği ya da kama kanalı kabul etmeyin. Diş genişliği, toplam göbek boyu, mil bağlantısı ve gerekiyorsa son işleme ölçüleri sipariş öncesinde karşılaştırılmalıdır. {m} modüllü bu pinyonda bağlantı biçiminin uygulamaya göre belirlenmesi, yalnız {z} diş üzerinden seçim yapılmasını önler.'), ('Kullanım Alanları', f'{model}; kremayerli konumlama mekanizmaları, malzeme besleme sistemleri, doğrusal taşıma düzenekleri ve makine yardımcı tahriklerinde değerlendirilebilir. Modül {m}, {z} diş ve {de} dış çapın uygunluğu; hareketli kütle, redüktör oranı, hız ve çevresel yükle birlikte belirlenir. Malzeme ve ısıl işlem değerleri belirtilmeden yalnız diş sayısından izin verilen tork veya ömür çıkarılamaz. Pinyonun görevi tahrik sağlamaktır; hareketli tablanın kılavuzlanması ayrı yataklarla ele alınır.'), ('Montaj ve Bakım', f'{model} takılırken dişlerin karşı kremayere tüm çalışma mesafesinde düzenli temas etmesi kontrol edilir. {z} dişli pinyonu kısa bir noktada sıkışmayacak şekilde ayarlamak tek başına yeterli değildir; kremayer ek yerleri ve uzunlamasına hizası da gözden geçirilmelidir. {m} modül için uygun yağlama ve koruma düzeni çalışma ortamına göre seçilir. Talaş ve yabancı parçaların diş arasına girmesi önlenmeli, bağlantı gevşekliği veya düzensiz ses görülürse mekanizma durdurularak nedeni araştırılmalıdır.')]
    if family == 'KR':
        length = v.get('Boy (L)', 'belirtilmemiş')
        dims = f'{v["Kesit Ölçüsü (a)"]} × {v["Kesit Ölçüsü (b)"]}' if 'Kesit Ölçüsü (a)' in v else '25 mm × 25 mm' if raw['orka_site'] else 'kesit ölçüsü belirtilmemiş'
        scope = 'kapı altı tahrik düzenleri' if raw.get('kapi_alti') else 'makine ve otomasyon eksenleri'
        return [('Kremayer Tahrik Elemanı', f'{model}, modül {m} kremayer grubunda {scope} için değerlendirilen doğrusal dişli elemanıdır. Pinyonun dönme hareketi kremayer boyunca ilerlemeye çevrilir; kremayer tek başına motor, kapı arabası veya lineer kılavuz değildir. Kesit bilgisi {dims}, boy bilgisi {length} olarak ele alınır. Teknik listede yer almayan kesit veya boyu model numarasındaki rakamlardan çıkararak montaj kararı vermeyin.'), ('Modül ve Hatve', f'{model} için modül {m} ve {v["Hatve (p)"]} hatve bilgisi birlikte değerlendirilir. Hatve, dişlerin uzunlamasına tekrarlanma aralığıdır; kesit yüksekliği veya bağlantı deliği aralığı değildir. Aynı modüldeki uygun düz pinyonla eşleştirme planlanırken diş profili, temas boşluğu ve tahrik ekseninin konumu ayrıca kontrol edilir. Sadece toplam boya dayanarak diş sayısı belirlemek, uçlardaki diş düzenini ve gerçek ürün kesimini gözden kaçırabilir.'), ('Yerleşim ve Bağlantı', f'{model} yerleşiminde {length} boyun mevcut olması, tamamının net hareket mesafesi olarak kullanılacağı anlamına gelmez. Pinyonun kapladığı bölge, hareket sonu payları ve mekanik sınırlar da hesaba katılır. {dims} kesit bilgisi, dişlerin çalışma yüksekliğini veya delik merkezlerini tek başına belirlemez. Modül {m} eksende bağlantı delikleri hazırlanmadan önce fiziksel parçanın montaj yüzeyini ve karşı pinyonun çalışma konumunu karşılaştırmak gerekir.'), ('Kullanım Alanları', f'{model}; {scope}, besleme hatları ve dönmeden doğrusal harekete geçiş gereken mekanizmalarda seçilebilir. Modül {m} dişli seçimi, sistemin taşıdığı yük ve hedeflenen hareket hızıyla birlikte yapılır. Kremayerin bağlandığı yüzeyin düzlüğü ve uzun bir eksende birden fazla parçanın hizası önemlidir. Ürün tipinden kapı ağırlığı, taşıma kapasitesi, hassasiyet sınıfı veya belirli bir yüzey sertliği varsayılmamalıdır; bunlar ayrı tasarım ve seçim koşullarıdır.'), ('Ek Yerleri ve Bakım', f'{model} kullanılan uzun bir tahrik hattında ek yerlerinin diş sırasını bozmaması gerekir. Modül {m} pinyonun her ekten geçişinde zorlanma veya darbe olup olmadığı düşük hızda kontrol edilir. Bağlantıların hareket boyunca düzgün kalması ve dişlerin talaş, kir veya yabancı cisimden korunması bakım planının parçasıdır. {length} boy bilgisi dışında belirtilmeyen montaj ayrıntıları, mevcut makine üzerinde ölçülmeden veya sipariş koşulları netleşmeden uygulanmamalıdır.')]
    if family == 'MKI':
        code = 'MKİ ' + model
        return [('İnce Seri Ayar Tabanı', f'{code}, motorun makine üzerindeki konumunun ayarlanması için kullanılan ince seri bir motor kızağıdır. Kayışlı tahrikte motor ile karşı kasnak arasındaki yerleşim ayarlanırken motor tabanının kontrollü olarak hareket ettirilmesine yönelik bir parçadır. Teknik tabloda C ölçüsü {v["Ölçü (C)"]}, G ölçüsü {v["Ölçü (G)"]} olarak verilir. Bu ölçüler birbirinin yerine kullanılmamalı; motorun kendi gövde boyu veya net ayar stroku olarak otomatik yorumlanmamalıdır.'), ('Motor Ayağı ile Karşılaştırma', f'{code} seçiminde motorun ayak delikleri, bağlantı cıvataları ve makine tabanına ayrılan alan birlikte kontrol edilir. A ölçüsü {v["Ölçü (A)"]}, B ölçüsü {v["Ölçü (B)"]} ve D ölçüsü {v["Ölçü (D)"]} değerlerini taşır. Harfler aynı ürünün ayrı ölçülerini tanımlar; bir harfe ait değeri başka bir üreticinin farklı harf düzenindeki çizimiyle eş anlamlı kabul etmeyin. Motorun yerleşimi fiziksel bağlantı yüzeyleri üzerinden karşılaştırılmalıdır.'), ('Ayar ve Sabitleme', f'{code} üzerindeki ayar mekanizması, motorun çalışma konumu belirlenirken kullanılır. Konum ayarlandıktan sonra taşıyıcı bağlantıların uygun şekilde sabitlenmesi gerekir; ayar vidası, bütün çalışma yükünü tek başına taşıyan bir bağlantı olarak görülmemelidir. H ölçüsü {v["Ölçü (H)"]}, M ölçüsü {v["Ölçü (M)"]} olarak listelenmiştir. Ayar sırasında kasnakların aynı düzlemde kalması ve kayışın yana zorlanmaması kontrol edilmelidir.'), ('Kullanım Alanları', f'{code}; kayış-kasnak tahrikleri, makine yardımcı motorları, fan ve pompa düzenekleri gibi motor konum ayarı gereken uygulamalarda değerlendirilebilir. İnce seri seçimi tek başına belirli bir motor gücünü veya ağırlığını garanti etmez. Motor ayak düzeni, çalışma titreşimi ve tabanın bağlantı koşulları birlikte ele alınır. N ölçüsü {v["Ölçü (N)"]}, O ölçüsü {v["Ölçü (O)"]} olan bu modeli yalnız seri numarasına bakarak başka bir kızakla eş ölçülü kabul etmeyin.'), ('Montaj Öncesi Kontrol', f'{code} için E ölçüsü {v["Ölçü (E)"]}, F ölçüsü {v["Ölçü (F)"]} ve S ölçüsü {v["Ölçü (S)"]} olarak verilmiştir. Motor ile kızağın temas yüzeyi temiz olmalı, ayar bölgesinde cıvata başlarının ve kasnağın hareketini engelleyen parçalar bulunmamalıdır. Kayış gerginliği ilgili tahrik elemanlarının koşullarına göre ayarlanır; gereğinden fazla germe motor yataklarına ek yük getirebilir. Bakımda bağlantı gevşekliği, ayar konumunun değişmesi ve kayış hizası birlikte kontrol edilmelidir.')]
    raise ValueError('Bilinmeyen aile: ' + family)


def product(raw, photo, index):
    title = identity(raw)
    family, model = raw['aile'], raw['model']
    specs = [(k, v['deger']) for k, v in raw['degerler'].items()] + [('Marka', 'Yamansa')]
    desc = '<div class="urunAciklama"><div class="teknikDetay"><h2>' + escape(title) + '</h2>'
    for heading, text in sections(raw, index):
        desc += '<h3>' + heading + '</h3><p>' + escape(text) + '</p>'
    links = [('kasnaklar', 'kasnaklar'), ('kayis', 'kayışlar')] if family == 'MKI' else [('duz-pinyonlar', 'düz pinyonlar'), ('duz-kremayerler', 'düz kremayerler')]
    desc += '<h3>İlgili Ürün Grupları</h3><p>' + escape(title) + ' için karşı parçaları '
    desc += ' ve '.join('<a href="https://www.yamansarulman.com/' + url + '">' + text + '</a>' for url, text in links)
    desc += ' kategorilerinden inceleyebilirsiniz. Modül, bağlantı düzeni ve çalışma alanını birlikte karşılaştırın.</p>'
    desc += '<h3>Teknik Özellikler</h3><ul>' + ''.join('<li><strong>' + escape(k) + ':</strong> ' + escape(v) + '</li>' for k, v in specs) + '</ul></div></div>'
    terms = [model, title, tr_lower(title), ascii_text(title), model.replace('M', 'M '), model.replace('M', 'M-')]
    terms += {'PD': ['düz pinyon', 'duz pinyon', 'pinyon dişli', 'pinyon disli', 'straight spur pinion', f'modül {raw["nominal"]}', f'module {raw["nominal"]}'], 'KR': ['kremayer ray', 'kremayer dişli', 'kremayer disli', 'straight gear rack', f'modül {raw["nominal"]}'], 'MKI': ['ince motor kızağı', 'ince motor kizagi', 'motor slide base', 'motor ayar tabanı', 'motor ayar tabani']}[family]
    words = ', '.join(dict.fromkeys(terms))
    item = dict(kod=raw['kod'], URUNADI=title, MARKA='Yamansa', KATEGORI=CATEGORIES[family], EK_KATEGORILER=[], yeni_kategori=family == 'MKI', ONYAZI=table(specs), ACIKLAMA=desc, ANAHTARKELIME=words, SEO_SAYFABASLIK=title, SEO_SAYFAACIKLAMA=title + '. Teknik ölçülerini ve montaj seçimini inceleyin.', SEO_ANAHTARKELIME=words, resim='gorseller/' + slug(title) + '.jpg', resim_seviye=photo['seviye'], resim_kaynak=photo['url'], teknik_kaynak=list(dict.fromkeys(v['kaynak'] for v in raw['degerler'].values())), bayraklar=raw['bayraklar'])
    ctx = dict(kod=raw['kod'], title=title, path='/' + slug(title), productId=index + 1, crumbs=['Anasayfa'] + CATEGORIES[family].split('>'), specs=[dict(l=k, v=v) for k, v in specs], onyazi=[dict(l=k, v=v) for k, v in specs], cizim_modulu=None)
    return item, ctx
